 @page "/notifications"
 @rendermode InteractiveServer
 @using NotificationsApp.Services
 @inject NotificationService NotificationService
 @implements IDisposable

 <PageTitle>Notifications</PageTitle>

 <h1>Notifications <span class="badge bg-primary">@(notifications?.Count ?? 0)</span></h1>

 @if (notifications is null || notifications.Count == 0)
 {
     <p><em>No notifications yet.</em></p>
 }
 else
 {
     <ul class="list-group">
         @foreach (var item in notifications.OrderByDescending(n => n.Timestamp))
         {
             <li class="list-group-item">
                 <strong>@item.Message</strong>
                 <small class="text-muted ms-2">@item.Timestamp.ToString("HH:mm:ss")</small>
             </li>
         }
     </ul>
 }

 @code {
     [PersistentState]
     public List<NotificationItem>? notifications { get; set; }

     private CancellationTokenSource? _cts;

     protected override async Task OnInitializedAsync()
     {
         // Only fetch if state wasn't restored from prerender
         notifications ??= await NotificationService.GetNotificationsAsync();
     }

     protected override void OnAfterRender(bool firstRender)
     {
         if (firstRender)
         {
             // Start polling only after the component is interactive (not during prerender)
             _cts = new CancellationTokenSource();
             _ = PollForNotificationsAsync(_cts.Token);
         }
     }

     private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
     {
         var lastSeenId = notifications is { Count: > 0 } ? notifications.Max(n => n.Id) : 0;

         while (!cancellationToken.IsCancellationRequested)
         {
             await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

             var newer = await NotificationService.GetNotificationsSinceAsync(lastSeenId);
             if (newer.Count > 0)
             {
                 notifications ??= new();
                 notifications.AddRange(newer);
                 lastSeenId = newer.Max(n => n.Id);
                 await InvokeAsync(StateHasChanged);
             }
         }
     }

     public void Dispose()
     {
         _cts?.Cancel();
         _cts?.Dispose();
     }
 }

